import { Text, View } from 'react-native'
import { useQuery } from '@tanstack/react-query'
import NetInfo, { useNetInfo } from '@react-native-community/netinfo'
import { BookButton } from './BookButton'
import { fetchMembership } from './api'

export function MembershipScreen() {
  const { data } = useQuery({ queryKey: ['membership'], queryFn: fetchMembership })
  const net = useNetInfo()
  if (!data) return <Text>Loading</Text>
  return (
    <View>
      {net.isConnected === false && <Text>Offline</Text>}
      <Text>{data.visitsLeft} visits left</Text>
      <Text>Next course {new Date(data.nextCourseAt).toLocaleTimeString()}</Text>
      <BookButton courseId={data.nextCourseId} />
    </View>
  )
}

