export type Entry = { seconds: number; rateCents: number }

export function csvAmount(e: Entry): number {
  return Math.round((e.seconds / 3600) * e.rateCents)
}

export function csv(entries: Entry[]): string {
  return entries.map((e) => `${e.seconds};${csvAmount(e)}`).join('\n')
}

