import type { Entry } from './csv'

export function invoiceAmount(e: Entry): number {
  const minutes = Math.round(e.seconds / 60)
  return Math.round((minutes / 60) * e.rateCents)
}

export function invoiceTotal(entries: Entry[]): number {
  return entries.reduce((sum, e) => sum + invoiceAmount(e), 0)
}
